result.output:
1	type Keyed = { id: string; category: string };
2	
3	function slotId(items: Keyed[], category: string): string | undefined {
4	  return items.find((i) => i.category === category)?.id;
5	}
6	
7	/**
8	 * Spread the shortlist across the wardrobe before the re-ranker sees it.
9	 *
10	 * Ranking alone clusters: a neutral top harmonises with everything, so combos
11	 * containing it occupy most of the top of the list. Hand that to the model and
12	 * it returns three variations of one outfit — not because it ignored the
13	 * instruction, but because that is what "the best 3" of a clustered list is.
14	 *
15	 * Constraining the INPUT is stronger than asking the model for variety in the
16	 * prompt: whichever three it picks from a diversified shortlist are distinct by
17	 * construction, with no compliance required.
18	 *
19	 * Greedy and score-ordered: walk the ranking, take a combo whose top and bottom
20	 * are both still unused, then backfill from the remainder. The best-scoring
21	 * combo is always kept and always first — diversity reorders what comes after
22	 * it, it never overrides the winner.
23	 *
24	 * Backfill matters: with two eligible tops, three distinct looks are impossible,
25	 * and repeating a garment is better than returning fewer candidates and starving
26	 * the re-ranker.
27	 */
28	export function diversify<T extends { items: Keyed[]; score: number }>(
29	  ranked: T[],
30	  n: number,
31	  minimum = 3,
32	): T[] {
33	  const usedTops = new Set<string>();
34	  const usedBottoms = new Set<string>();
35	  const picked: T[] = [];
36	  const rest: T[] = [];
37	
38	  for (const r of ranked) {
39	    if (picked.length >= n) {
40	      rest.push(r);
41	      continue;
42	    }
43	    const top = slotId(r.items, "Tops");
44	    const bottom = slotId(r.items, "Bottoms");
45	    // A missing slot cannot collide — an accessory-only or shoes-only combo is
46	    // not "sharing" a top with anything.
47	    const fresh =
48	      (top === undefined || !usedTops.has(top)) &&
49	      (bottom === undefined || !usedBottoms.has(bottom));
50	
51	    if (!fresh) {
52	      rest.push(r);
53	      continue;
54	    }
55	    picked.push(r);
56	    if (top !== undefined) usedTops.add(top);
57	    if (bottom !== undefined) usedBottoms.add(bottom);
58	  }
59	
60	  // Backfill ONLY to the floor, never to `n`.
61	  //
62	  // A 10-top / 6-bottom closet yields 6 genuinely distinct combos, so padding a
63	  // 20-slot shortlist would hand the re-ranker 14 repeats it is free to choose —
64	  // reintroducing the duplicate looks this function exists to prevent. A short,
65	  // clean shortlist is better than a long, padded one; the floor exists only so
66	  // a wardrobe too small for three distinct looks still gets three looks.
67	  const floor = Math.min(minimum, n); // asking for 2 must never return 3
68	  for (const r of rest) {
69	    if (picked.length >= floor) break;
70	    picked.push(r);
71	  }
72	  return picked;
73	}
74

1	import { diversify } from "../diversity";
2	
3	const combo = (id: string, top: string, bottom: string, score: number) => ({
4	  id,
5	  score,
6	  items: [
7	    { id: top, category: "Tops" },
8	    { id: bottom, category: "Bottoms" },
9	    { id: "shoe", category: "Shoes" },
10	  ],
11	});
12	
13	// Score order, but the first three all share the cream top — which is exactly
14	// what a ranked list looks like when one neutral piece harmonises with
15	// everything. Handing that to the re-ranker guarantees repeats no matter what
16	// the prompt asks for.
17	const ranked = [
18	  combo("a", "cream", "navy", 0.9),
19	  combo("b", "cream", "stone", 0.89),
20	  combo("c", "cream", "navy", 0.88),
21	  combo("d", "navy-top", "stone", 0.8),
22	  combo("e", "olive-top", "black", 0.7),
23	];
24	
25	test("the best-scoring combo is always kept, and kept first", () => {
26	  expect(diversify(ranked, 3)[0].id).toBe("a");
27	});
28	
29	test("no two of the returned looks share a top", () => {
30	  const tops = diversify(ranked, 3).map((r) => r.items.find((i) => i.category === "Tops")!.id);
31	  expect(new Set(tops).size).toBe(3);
32	});
33	
34	test("no two of the returned looks share a bottom", () => {
35	  const bottoms = diversify(ranked, 3).map(
36	    (r) => r.items.find((i) => i.category === "Bottoms")!.id,
37	  );
38	  expect(new Set(bottoms).size).toBe(3);
39	});
40	
41	test("the diverse set stays in score order", () => {
42	  const scores = diversify(ranked, 3).map((r) => r.score);
43	  expect(scores).toEqual([...scores].sort((x, y) => y - x));
44	});
45	
46	test("a closet that cannot diversify still returns n, rather than dropping looks", () => {
47	  // Two tops, two bottoms — three distinct looks are impossible. Repeating a
48	  // garment beats showing fewer looks, so the shortlist is backfilled.
49	  const cramped = [
50	    combo("a", "cream", "navy", 0.9),
51	    combo("b", "cream", "navy", 0.8),
52	    combo("c", "cream", "navy", 0.7),
53	  ];
54	  expect(diversify(cramped, 3)).toHaveLength(3);
55	  expect(diversify(cramped, 3)[0].id).toBe("a");
56	});
57	
58	test("backfill comes in score order too", () => {
59	  const cramped = [
60	    combo("a", "cream", "navy", 0.9),
61	    combo("b", "cream", "navy", 0.8),
62	    combo("c", "cream", "navy", 0.7),
63	  ];
64	  expect(diversify(cramped, 3).map((r) => r.id)).toEqual(["a", "b", "c"]);
65	});
66	
67	test("returns at most n", () => {
68	  expect(diversify(ranked, 2)).toHaveLength(2);
69	});
70	
71	test("a large shortlist is NOT padded with repeats to fill it", () => {
72	  // The fixture has only three combos with a distinct top+bottom (a, d, e).
73	  // Padding the remaining 96 slots with repeats would hand the re-ranker
74	  // duplicates it is free to pick — reintroducing the exact bug this prevents.
75	  // A short clean shortlist beats a long padded one.
76	  const out = diversify(ranked, 99);
77	  expect(out).toHaveLength(3);
78	  const tops = out.map((r) => r.items.find((i) => i.category === "Tops")!.id);
79	  expect(new Set(tops).size).toBe(3);
80	});
81	
82	test("the floor never exceeds the requested size", () => {
83	  // minimum defaults to 3; asking for 2 must still return 2.
84	  expect(diversify(ranked, 2)).toHaveLength(2);
85	});
86	
87	test("an empty ranking returns empty rather than throwing", () => {
88	  expect(diversify([], 3)).toEqual([]);
89	});
90	
91	test("a combo missing a category is not treated as sharing one", () => {
92	  const shoesOnly = [
93	    { id: "x", score: 0.9, items: [{ id: "shoe1", category: "Shoes" }] },
94	    { id: "y", score: 0.8, items: [{ id: "shoe2", category: "Shoes" }] },
95	  ];
96	  expect(diversify(shoesOnly, 2)).toHaveLength(2);
97	});
